% MATLAB Reference Script for Flow Through Helical and Spiral Coils

% Fixed apparatus dimensions
Dp = 0.021;     % Pipe diameter (m)
Dc = 0.014;     % Coil diameter (m)
L = 5.6;        % Pipe length (m)
rho = 1000.0;   % Water density (kg/m^3)
mu = 0.01;      % Dynamic viscosity (kg/(m*s))
g = 9.81;       % Gravity (m/s^2)
A = (pi / 4) * Dp^2;

% Critical Reynolds number
N_REC = 2100 * (1 + 12 * sqrt(Dp / Dc));
fprintf('Critical Reynolds Number NREC = %.0f\n', N_REC);

% Helical Coil Readings
Q_helical = [1.5e-4, 2.0e-4, 3.0e-4];
V_helical = Q_helical ./ A;
NRe_helical = (rho .* V_helical .* Dp) ./ mu;
fc_helical = 0.08 .* (NRe_helical .^ -0.25) + 0.01 * sqrt(Dp / Dc);

% Spiral Coil Readings
Q_spiral = [1.8e-4, 2.0e-4, 3.0e-4];
V_spiral = Q_spiral ./ A;
NRe_spiral = (rho .* V_spiral .* Dp) ./ mu;
fc_spiral = 0.08 .* (NRe_spiral .^ -0.25) + 0.01 * sqrt(Dp / Dc);

figure;
plot(NRe_helical, fc_helical, 'o-', 'Color', [0 0.447 0.741], 'LineWidth', 1.8, 'DisplayName', 'Helical Coil');
hold on;
plot(NRe_spiral, fc_spiral, 's--', 'Color', [0.85 0.325 0.098], 'LineWidth', 1.8, 'DisplayName', 'Spiral Coil');
grid on; box on;
xlabel('Reynolds Number (NRe)');
ylabel('Coil Friction Factor (fc)');
title('Coil Friction Factor vs Reynolds Number');
legend('Location', 'northeast');
